function decN(n){const k=n%100,m=n%10;return n+' '+((k<11||k>14)&&m===1?'публикация':(k<11||k>14)&&m>=2&&m<=4?'публикации':'публикаций');}

let DEC_QUERY='',DEC_WEEK='';
const DEC_PLATS=['Все','Telegram','ВК','Instagram','Менеджеры'];
function decPlatform(r){
 if(r.channel==='TG компании'||r.channel==='TG Романа'||r.channel==='TG Кирилла')return'Telegram';
 if(r.channel==='TG Екатерины'||r.channel==='TG Оксаны')return'Менеджеры';
 if(r.channel==='VK'||r.channel==='VK Клипы')return'ВК';
 return'Instagram';
}
function decLabel(ch){return({'TG компании':'Юнитрамп','TG Романа':'Роман Сотников','TG Кирилла':'Кирилл Шувалов','TG Екатерины':'Екатерина Тюкавкина','TG Оксаны':'Оксана Журман',VK:'Публикации ВК','VK Клипы':'ВК Клипы',Instagram:'Лента Instagram','IG Reels':'Instagram Reels'})[ch]||ch;}
function decCount(p){return p==='Все'?DEC_POSTS.length:DEC_POSTS.filter(r=>decPlatform(r)===p).length;}
function decEsc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function decMedia(r){
 if(!r.media_items?.length)return'';
 return '<div class="d5media">'+r.media_items.map((m,i)=>{
 let visual=m.kind==='video'?'<video controls muted playsinline preload="none" poster="'+decEsc(m.poster)+'" src="'+decEsc(m.file)+'"></video>':'<a href="'+decEsc(m.file)+'" target="_blank" rel="noopener"><img loading="lazy" src="'+decEsc(m.file)+'" alt="'+decEsc(r.title)+' · '+(i+1)+'"></a>';
 return '<figure>'+visual+'<figcaption>'+decEsc(m.caption||'')+' <a href="'+decEsc(m.file)+'" download>Скачать'+(r.media_items.length>1?' '+(i+1):'')+'</a></figcaption></figure>';
 }).join('')+'</div>';
}
function decCard(r){
 const id='d5-'+r.id;
 return '<article class="d5card" data-dec-card data-dec-week="'+Math.min(5,Math.floor((Number(r.date.slice(-2))-1)/7)+1)+'" id="'+decEsc(r.id)+'"><div class="d5meta"><span>'+decEsc(r.id)+'</span><b>'+r.date.slice(-2)+'.12 · '+decEsc(r.time)+' ЕКБ</b><span>'+decEsc(decLabel(r.channel))+'</span></div><h2>'+decEsc(r.title)+'</h2><div class="d5format">'+decEsc(r.format)+'</div>'+decMedia(r)+'<pre class="d5text" id="'+decEsc(id)+'">'+r.text_html+'</pre><div class="d5buttons"><button onclick="cp(\''+decEsc(id)+'\',this)">Скопировать с оформлением</button><button onclick="cp(\''+decEsc(id)+'\',this,true)">Обычный текст</button></div></article>';
}
